NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paavali, Kristuksen Jeesuksen apostoli, Jumalan, meidän vapahtajamme, ja Kristuksen Jeesuksen, meidän toivomme, käskystä,',
        2: 'Timoteukselle, oikealle pojalleen uskossa. Armo, laupeus ja rauha Jumalalta Isältämme ja Kristukselta Jeesukselta, Herraltamme!',
        3: 'Niin kuin Makedoniaan lähtiessäni kehotin sinua jäämään Efesoon käskeäksesi, etteivät opettaisi muita oppeja',
        4: 'eivätkä kiinnittäisi huomiota taruihin ja loputtomiin sukuluetteloihin, jotka saavat aikaan ennemmin riitoja kuin rakentavat Jumalan huonetta uskossa.',
        5: 'Mutta käskyn päämäärä on rakkaus, joka tulee puhtaasta sydämestä, hyvästä omastatunnosta ja teeskentelemättömästä uskosta.',
        6: 'Muutamat ovat hairahtuneet niistä pois ja kääntyneet puhumaan turhia,',
        7: 'tahtoen olla lainopettajia, vaikka eivät ymmärrä, mitä puhuvat ja minkä varmaksi väittävät.',
        8: 'Mutta tiedämme, että laki on hyvä, kun sitä lain mukaisesti käytetään',
        9: 'ja tiedetään, että lakia ei ole pantu vanhurskaalle, vaan laittomille ja niskoitteleville, jumalattomille ja syntisille, epähurskaille ja epäpyhille, isänsä tappajille ja äitinsä tappajille, murhaajille,',
        10: 'haureellisille, miesten kanssa makaaville miehille, ihmiskauppiaille, valehtelijoille, valansa rikkojille ja kaikelle muulle, mikä on tervettä oppia vastaan –',
        11: 'autuaan Jumalan kirkkauden evankeliumin mukaisesti, joka on minulle uskottu.',
        12: 'Minä kiitän häntä, joka on minulle voimaa antanut, Kristusta Jeesusta, meidän Herraamme, siitä, että hän katsoi minut uskolliseksi ja asetti palvelusvirkaan',
        13: 'minut, entisen pilkkaajan, vainoojan ja väkivallantekijän. Mutta sain laupeuden, koska olin tehnyt sitä tietämättömänä, epäuskossa,',
        14: 'ja meidän Herramme armo oli ylitsepursuava uskon ja rakkauden kanssa, joka on Kristuksessa Jeesuksessa.',
        15: 'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen, että Kristus Jeesus on tullut maailmaan pelastamaan syntisiä, joista minä olen ensimmäinen.',
        16: 'Mutta sen tähden sain laupeuden, jotta Jeesus Kristus minussa ennen muita osoittaisi kaiken pitkämielisyytensä esikuvaksi niille, jotka tulevat uskomaan häneen itselleen iankaikkiseksi elämäksi.',
        17: 'Mutta iankaikkiselle kuninkaalle, katoamattomalle, näkymättömälle, Jumalalle, ainoalle viisaalle, kunnia ja kirkkaus iäisyyksien iäisyyksiin! Aamen.',
        18: 'Tämän käskyn annan sinulle, poikani Timoteus, aikaisempien, sinulle lausuttujen profetioiden mukaisesti, että niiden mukaisesti taistelisit hyvän taistelun,',
        19: 'säilyttäen uskon ja hyvän omantunnon, jonka eräät ovat hylänneet ja uskossaan haaksirikkoutuneet.',
        20: 'Niitä ovat Hymeneus ja Aleksander, jotka olen antanut saatanan kuritettaviksi, etteivät enää pilkkaisi.',
    },
    2: {
        1: 'Kehotan siis ennen kaikkea anomaan, rukoilemaan, pitämään esirukouksia ja kiittämään kaikkien ihmisten puolesta,',
        2: 'kuningasten ja kaiken esivallan puolesta, että saisimme viettää rauhallista ja hiljaista elämää kaikessa jumalanpelossa ja kunniallisuudessa.',
        3: 'Sillä se on hyvää ja otollista Jumalalle, vapahtajallemme,',
        4: 'joka tahtoo, että kaikki ihmiset pelastuisivat ja tulisivat tuntemaan totuuden.',
        5: 'Sillä yksi on Jumala, yksi myös välimies Jumalan ja ihmisten välillä, ihminen Kristus Jeesus,',
        6: 'joka antoi itsensä lunnaiksi kaikkien edestä ja josta todistus oli annettava ajallaan,',
        7: 'ja sitä varten minut on saarnaajaksi ja apostoliksi asetettu – puhun totta, en valehtele – pakanain opettajaksi uskossa ja totuudessa.',
        8: 'Tahdon siis, että miehet rukoilevat, joka paikassa kohottaen pyhät kädet ilman vihaa ja epäilystä;.',
        9: 'samoin, että naiset ovat säädyllisessä puvussa, kaunistavat itseään kainosti ja kohtuullisesti, ei palmikoiduilla hiuksilla, kullalla, helmillä eikä kallisarvoisilla vaatteilla,',
        10: 'vaan hyvillä teoilla, kuten on soveliasta naisille, jotka tunnustautuvat jumalaapelkääviksi.',
        11: 'Oppikoon nainen hiljaisuudessa, kaikin puolin alistuvana.',
        12: 'Mutta en salli, että nainen opettaa, enkä että hän vallitsee miestä, vaan olkoon hiljaisuudessa.',
        13: 'Sillä Aadam luotiin ensin, sitten Eeva,',
        14: 'eikä Aadamia petetty, vaan nainen petettiin ja rikkoi.',
        15: 'Mutta hän on pelastuva lastensynnyttämisen kautta, jos hän pysyy uskossa, rakkaudessa ja pyhityksessä noudattaen itsehillintää.',
    },
    3: {
        1: 'Varma on tämä sana: jos joku pyrkii kaitsijan virkaan, hän haluaa jaloon toimeen.',
        2: 'Kaitsijan tulee siis olla nuhteeton, yhden vaimon mies, raitis, hurskas, kunniallinen, vieraanvarainen, kykenevä opettamaan,',
        3: 'ei juomari, ei tappelija, ei häpeällistä voittoa tavoitteleva, vaan lempeä, ei riitaisa, ei rahanahne,',
        4: 'vaan oman kotinsa hyvin hallitseva ja kaikella kunniallisuudella lapsensa kuuliaisina pitävä.',
        5: 'Sillä jos joku ei osaa hallita omaa kotiaan, kuinka hän huolehtii Jumalan seurakunnasta?',
        6: 'Älköön hän olko äsken kääntynyt, ettei paisuisi ja joutuisi perkeleen tuomion alaiseksi.',
        7: 'Hänellä tulee myös olla hyvä todistus ulkopuolella olevilta, ettei hän joutuisi perkeleen häväistäväksi ja hänen paulaansa.',
        8: 'Samoin diakonien tulee olla arvokkaita, ei kahdella tavalla puhuvia, ei paljon viinin nauttijoita, ei häpeällisen voiton pyytäjiä,',
        9: 'sellaisia, jotka pitävät uskon salaisuuden puhtaassa omassatunnossa.',
        10: 'Mutta heitäkin koeteltakoon ensin, sitten palvelkoot, jos ovat nuhteettomia.',
        11: 'Samoin tulee naistenkin olla arvokkaita, ei panettelijoita, vaan raittiita, uskollisia kaikessa.',
        12: 'Diakonit olkoot yhden vaimon miehiä, lapsensa ja oman kotinsa hyvin hallitsevia.',
        13: 'Sillä ne, jotka ovat hyvin palvelleet, saavuttavat itselleen kunnioitettavan aseman ja suuren rohkeuden uskossa Kristukseen Jeesukseen.',
        14: 'Kirjoitan tämän sinulle – vaikka toivonkin pian pääseväni luoksesi –',
        15: 'että, jos viivyn, tietäisit, miten tulee olla Jumalan huoneessa, joka on elävän Jumalan seurakunta, totuuden pylväs ja perustus.',
        16: 'Tunnustetusti suuri on jumalanpelon salaisuus: Jumala on ilmestynyt lihassa, vanhurskaaksi julistettu Hengessä, näyttäytynyt enkeleille, saarnattu pakanoiden keskuudessa, uskottu maailmassa, otettu ylös kirkkauteen.',
    },
    4: {
        1: 'Mutta Henki sanoo selvästi, että tulevina aikoina monet luopuvat uskosta ja noudattavat villitseviä henkiä ja riivaajien oppeja',
        2: 'valheenpuhujien ulkokultaisuuden vaikutuksesta, joiden omatunto on poltinraudalla merkitty.',
        3: 'He kieltävät menemästä naimisiin ja nauttimasta ruokia, jotka Jumala on luonut niiden nautittavaksi kiitoksella, jotka uskovat ja ovat tulleet totuuden tuntemaan.',
        4: 'Sillä kaikki, minkä Jumala on luonut, on hyvää, eikä mikään ole hylättävää, kun se kiitoksella vastaanotetaan,',
        5: 'sillä se pyhitetään Jumalan sanalla ja rukouksella.',
        6: 'Kun tätä veljille opetat, olet hyvä Kristuksen Jeesuksen palvelija, joka ravitset itseäsi uskon ja sen hyvän opin sanoilla, jota olet noudattanut.',
        7: 'Mutta epäpyhiä akkojen taruja karta ja harjoita itseäsi jumalanpelkoon.',
        8: 'Sillä ruumiillisesta harjoituksesta on hyötyä vain vähään, mutta jumalanpelosta on hyötyä kaikkeen, koska sillä on elämän lupaus, sekä nykyisen että tulevan.',
        9: 'Varma on se sana ja kaikin puolin vastaanottamisen arvoinen.',
        10: 'Sillä siksi näemme vaivaa ja kilvoittelemme, että olemme panneet toivomme elävään Jumalaan, joka on kaikkien ihmisten vapahtaja, varsinkin uskovien.',
        11: 'Tätä käske ja opeta.',
        12: 'Älköön kukaan halveksiko nuoruuttasi, vaan ole sinä uskovien esikuva puheessa, vaelluksessa, rakkaudessa, hengessä, uskossa, puhtaudessa.',
        13: 'Lue, kehota ja opeta ahkerasti, kunnes tulen.',
        14: 'Älä lyö laimin armolahjaa, joka sinussa on ja joka sinulle annettiin profetian kautta vanhinten pannessa kätensä päällesi.',
        15: 'Harrasta näitä, elä näissä, jotta edistymisesi olisi kaikkien nähtävissä.',
        16: 'Valvo itseäsi ja opetustasi, ole siinä kestävä. Sillä jos sen teet, olet pelastava sekä itsesi että ne, jotka sinua kuulevat.',
    },
    5: {
        1: 'Älä nuhtele kovasti vanhaa miestä, vaan kehota häntä kuin isää, nuorempia kuin veljiä,',
        2: 'vanhoja naisia kuin äitejä, nuorempia kuin sisaria, kaikessa puhtaudessa.',
        3: 'Kunnioita leskiä, jotka ovat oikeita leskiä.',
        4: 'Mutta jos jollakulla leskellä on lapsia tai lapsenlapsia, oppikoot nämä ensin jumalisesti hoitamaan omaa perhekuntaansa ja maksamaan velkansa vanhemmilleen, sillä se on oikein ja otollista Jumalan edessä.',
        5: 'Oikea leski ja yksinäiseksi jäänyt panee toivonsa Jumalaan, anoo ja rukoilee alinomaa, yötä päivää.',
        6: 'Mutta se, joka haluaa viettää ylellistä elämää, on jo eläessään kuollut.',
        7: 'Käske tätäkin, että olisivat nuhteettomia.',
        8: 'Mutta jos joku ei pidä huolta omaisistaan ja varsinkaan perhekuntalaisistaan, hän on kieltänyt uskon ja on epäuskoista pahempi.',
        9: 'Luetteloon otettakoon ainoastaan sellainen leski, joka ei ole kuuttakymmentä vuotta nuorempi ja joka on ollut yhden miehen vaimo,',
        10: 'josta on todistettu, että hän on tehnyt hyviä töitä, on kasvattanut lapsia, holhonnut vieraita, pessyt pyhien jalkoja, auttanut ahdistettuja ja harrastanut kaiken hyvän tekemistä.',
        11: 'Mutta nuorehkot lesket hylkää, sillä kun he himokkaiksi käyden vieraantuvat Kristuksesta, he tahtovat mennä naimisiin,',
        12: 'ja ovat tuomion alaisia, koska ovat hylänneet ensimmäisen uskonsa.',
        13: 'He oppivat taloissa kierrellessään laiskoiksikin, eikä ainoastaan laiskoiksi, vaan myös juoruamaan, sekaantumaan toisten asioihin ja puhumaan sopimattomia.',
        14: 'Tahdon sen tähden nuorempien menevän naimisiin, synnyttävän lapsia, hoitavan kotiaan ja etteivät anna vastustajalle mitään aihetta solvaamiseen.',
        15: 'Sillä muutamat ovat jo kääntyneet pois seuraamaan saatanaa.',
        16: 'Jos jollakulla uskovalla naisella on leskiä, pitäköön heistä huolen, älköönkä seurakuntaa rasitettako, että se voisi pitää huolta oikeista leskistä.',
        17: 'Vanhimpia, jotka seurakuntaa hyvin hoitavat, pidettäköön kaksinkertaisen kunnian ansainneina, varsinkin niitä, jotka tekevät työtä sanassa ja opetuksessa.',
        18: 'Sillä Raamattu sanoo: "Älä sido puivan härän suuta", ja: "Työmies on palkkansa ansainnut."',
        19: 'Älä ota käsiteltäväksi syytöstä vanhinta vastaan, ellei ole kahta tai kolmea todistajaa.',
        20: 'Syntiä tekeviä nuhtele kaikkien edessä, että muutkin pelkäisivät.',
        21: 'Vannotan sinua Jumalan ja Herran Kristuksen Jeesuksen ja valittujen enkelien edessä, että noudatat tätä tekemättä etukäteen päätöstä ja ketään suosimatta.',
        22: 'Älä ole liian hätäinen panemaan käsiäsi kenenkään päälle, äläkä osallistu muiden synteihin. Pidä itsesi puhtaana.',
        23: 'Älä enää juo vain vettä, vaan käytä vähän viiniä vatsasi tähden ja usein uudistuvien vaivojesi vuoksi.',
        24: 'Muutamien ihmisten synnit ovat ilmeiset ja joutuvat ennen tuomittaviksi, toisten taas seuraavat perästäpäin.',
        25: 'Samoin myös hyvät teot ovat ilmeiset, eivätkä nekään, jotka eivät ole sellaisia, voi pysyä salassa.',
    },
    6: {
        1: 'Kaikki, jotka ovat orjina ikeen alla, pitäkööt isäntiään kaiken kunnioituksen arvoisina, jotta Jumalan nimeä ja oppia ei häväistäisi.',
        2: 'Mutta ne, joilla on uskovat isännät, älkööt pitäkö heitä vähemmässä arvossa sen tähden, että he ovat veljiä, vaan palvelkoot heitä sitä mieluummin, koska he ovat uskovia ja rakastettuja ja ottavat osaa hyvän tekemiseen. Tätä opeta ja kehota.',
        3: 'Jos joku opettaa muuta oppia eikä pitäydy Herramme Jeesuksen Kristuksen terveisiin sanoihin eikä siihen oppiin, joka on jumalanpelon mukainen,',
        4: 'hän on ylpistynyt eikä ymmärrä mitään, vaan on riitakysymysten ja sanakiistojen kipeä. Niistä syntyy kateutta, riitaa, herjauksia, pahoja epäluuloja,',
        5: 'alituisia kiistoja niiden ihmisten kesken, jotka ovat turmeltuneet mieleltään ja totuuden menettäneet ja jotka pitävät jumalanpelkoa keinona voiton saamiseen. Pysy erossa sellaisista.',
        6: 'Mutta suuri voitto onkin jumalanpelko yhdessä tyytyväisyyden kanssa.',
        7: 'Sillä emme ole tuoneet mitään maailmaan. Selvää on, ettemme voi myöskään täältä mitään viedä.',
        8: 'Mutta kun meillä on elatus ja vaatteet, tyytykäämme niihin.',
        9: 'Mutta ne, jotka rikastua tahtovat, lankeavat kiusaukseen ja ansaan sekä moniin mielettömiin ja vahingollisiin himoihin, jotka upottavat ihmiset turmioon ja kadotukseen.',
        10: 'Sillä rahan himo on kaiken pahan juuri. Sitä haluten monet ovat eksyneet pois uskosta ja lävistäneet itsensä monella tuskalla.',
        11: 'Mutta sinä, Jumalan ihminen, pakene sellaista ja tavoittele vanhurskautta, jumalanpelkoa, uskoa, rakkautta, kärsivällisyyttä ja hiljaisuutta.',
        12: 'Kilvoittele hyvä uskon kilvoitus, tartu kiinni iankaikkiseen elämään, johon olet kutsuttu ja johon olet hyvällä tunnustuksella tunnustautunut monen todistajan edessä.',
        13: 'Jumalan edessä, joka kaiken eläväksi tekee, ja Kristuksen Jeesuksen edessä, joka Pontius Pilatuksen edessä todisti, tunnustaen hyvän tunnustuksen, kehotan sinua,',
        14: 'että pidät tahrattomasti ja moitteettomasti käskyn meidän Herramme Jeesuksen Kristuksen ilmestymiseen saakka.',
        15: 'Sen on aikanaan antava meidän nähdä autuas ja ainoa valtias, kuningasten Kuningas ja herrojen Herra,',
        16: 'jolla ainoalla on kuolemattomuus; joka asuu valkeudessa, mitä kukaan ei voi lähestyä; jota yksikään ihminen ei ole nähnyt eikä voi nähdä – hänen olkoon kunnia ja iankaikkinen valta. Aamen.',
        17: 'Kehota niitä, jotka nykyisessä maailmanajassa ovat rikkaita, etteivät ylpeilisi eivätkä panisi toivoaan epävarmaan rikkauteen, vaan elävään Jumalaan, joka antaa meille runsaasti kaikkea nautittavaksemme.',
        18: 'Kehota heitä, että tekevät hyvää, hyvissä töissä rikastuvat, ovat anteliaita ja jakavat omastaan,',
        19: 'kooten itselleen aarteen, hyvän perustuksen tulevaisuuden varalle, jotta tarttuisivat kiinni iankaikkiseen elämään.',
        20: 'Timoteus, talleta se, mikä sinulle on uskottu, ja pysy erossa tiedon nimellä kulkevan valhetiedon epäpyhistä ja tyhjistä puheista ja vastaväitteistä.',
        21: 'Siihen tunnustautuen muutamat ovat uskosta hairahtuneet. Armo kanssasi! Aamen.',
    },
}
